const core = ["Chrome", "Chrome Android", "Edge", "Firefox",
  "Firefox Android", "Safari", "Safari iOS"];
function baselineStatus(supportedIn, monthsSinceNewly) {
  if (!core.every((b) => supportedIn.includes(b)))
    return "Limited availability";
  if (monthsSinceNewly < 30)
    return "Newly available";
  return "Widely available";
}
